// Regression for native vehicle crew escape while the infantry pool is full.
#define Generate_Mission_Starts SAM_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Reset(dir);auto bad=HouseClass::As_Pointer(HOUSE_BAD);bad->IsActive=true;bad->IsDefeated=false;while(Infantry.Count()<INFANTRY_MAX){auto f=new InfantryClass(INFANTRY_E1,HOUSE_BAD);if(!f)break;}Check("fill the native infantry pool completely",Infantry.Count()==INFANTRY_MAX);auto extra=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("full infantry pool returns null without constructing",extra==nullptr);for(int seed=1;seed<=20;++seed){auto vehicle=new UnitClass(UNIT_HARVESTER,HOUSE_BAD);Check("unarmed destroyed vehicle has a crew escape branch",vehicle->Class->IsCrew&&vehicle->Class->Primary==WEAPON_NONE);Check("place full-pool crew test vehicle",Put(vehicle,Center()));Scen.RandomNumber=seed;std::printf("FULL POOL CREW DESTRUCTION seed=%d\n",seed);std::fflush(stdout);int damage=10000;vehicle->Take_Damage(damage,0,WARHEAD_PB,nullptr);Check("full-pool vehicle destruction does not allocate a crew",Infantry.Count()==INFANTRY_MAX);}delete Infantry.Ptr(Infantry.Count()-1);for(int seed=1;seed<=20&&Infantry.Count()<INFANTRY_MAX;++seed){auto vehicle=new UnitClass(UNIT_HARVESTER,HOUSE_BAD);Put(vehicle,Center());Scen.RandomNumber=seed;int damage=10000;vehicle->Take_Damage(damage,0,WARHEAD_PB,nullptr);}int technicians=0;for(int i=0;i<Infantry.Count();++i)if(!Infantry.Ptr(i)->IsInLimbo&&Infantry.Ptr(i)->IsTechnician)++technicians;Check("normal crew escape still creates a technician when a slot is available",Infantry.Count()==INFANTRY_MAX&&technicians==1);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
